-- ADOS-2 Module 4 score descriptions
-- Adolescentes y adultos con fluidez verbal

INSERT INTO ados2_score_descriptions (module, item_code, item_name, domain, score_value, description)
VALUES
-- A. Lenguaje y Comunicación
('4', 'A-1', 'Nivel general de lenguaje no ecolálico', 'Lenguaje y Comunicación', 0, 'Utiliza oraciones generalmente de forma correcta (debe utilizar algunas verbalizaciones complejas de dos o más cláusulas).'),
('4', 'A-1', 'Nivel general de lenguaje no ecolálico', 'Lenguaje y Comunicación', 1, 'Cierta complejidad del habla (en ocasiones utiliza verbalizaciones de dos o más cláusulas) pero con errores gramaticales recurrentes.'),
('4', 'A-1', 'Nivel general de lenguaje no ecolálico', 'Lenguaje y Comunicación', 2, 'El habla no ecolálica se compone principalmente de verbalizaciones de por lo menos 3 o más palabras, pero las frases simples no son elípticas.'),
('4', 'A-1', 'Nivel general de lenguaje no ecolálico', 'Lenguaje y Comunicación', 3, 'El habla no ecolálica consiste principalmente en frases simples.'),

('4', 'A-2', 'Anormalidades del habla asociadas con autismo (entonación, volumen, ritmo y velocidad)', 'Lenguaje y Comunicación', 0, 'Entonación que varía apropiadamente, volumen razonable y velocidad normal del habla, con un ritmo regular coordinado con la respiración.'),
('4', 'A-2', 'Anormalidades del habla asociadas con autismo (entonación, volumen, ritmo y velocidad)', 'Lenguaje y Comunicación', 1, 'Poca variación de timbre y tono; más bien monótono o exagerado, pero sin una entonación claramente peculiar; o tiene un volumen levemente inusual; o tiene un habla que tiende a ser inapropiadamente lenta o rápida o espasmódica.'),
('4', 'A-2', 'Anormalidades del habla asociadas con autismo (entonación, volumen, ritmo y velocidad)', 'Lenguaje y Comunicación', 2, 'Habla claramente anormal: lenta y vacilante; inapropiadamente rápida; espasmódica y con un ritmo irregular; entonación rara o timbre o acento inapropiado; marcadamente monótona y sin entonación; volumen consistentemente anormal.'),
('4', 'A-2', 'Anormalidades del habla asociadas con autismo (entonación, volumen, ritmo y velocidad)', 'Lenguaje y Comunicación', 7, 'Tartamudeo u otro trastorno de la fluencia verbal.'),
('4', 'A-2', 'Anormalidades del habla asociadas con autismo (entonación, volumen, ritmo y velocidad)', 'Lenguaje y Comunicación', 8, 'N/A (el habla no se da con la suficiente frecuencia o complejidad como para evaluar entonación/ritmo/velocidad).'),

('4', 'A-3', 'Ecolalia inmediata', 'Lenguaje y Comunicación', 0, 'Rara vez o nunca repite el habla de otra persona.'),
('4', 'A-3', 'Ecolalia inmediata', 'Lenguaje y Comunicación', 1, 'Eco ocasional del habla de otros.'),
('4', 'A-3', 'Ecolalia inmediata', 'Lenguaje y Comunicación', 2, 'Repite palabras o frases con regularidad, pero también posee lenguaje espontáneo (puede ser estereotipado).'),
('4', 'A-3', 'Ecolalia inmediata', 'Lenguaje y Comunicación', 3, 'El habla consiste principalmente en ecolalia inmediata.'),

('4', 'A-4', 'Uso estereotipado o idiosincrásico de palabras o frases', 'Lenguaje y Comunicación', 0, 'Rara vez o nunca usa palabras o frases estereotipadas o idiosincrásicas.'),
('4', 'A-4', 'Uso estereotipado o idiosincrásico de palabras o frases', 'Lenguaje y Comunicación', 1, 'El uso de palabras o frases tiende a ser más repetitivo o formal que en la mayoría de los individuos con el mismo nivel de complejidad, pero no es claramente raro; u ocasionalmente produce vocalizaciones estereotipadas o hace uso de palabras raras o emplea frases de forma inusual, junto con otro lenguaje espontáneo flexible.'),
('4', 'A-4', 'Uso estereotipado o idiosincrásico de palabras o frases', 'Lenguaje y Comunicación', 2, 'A menudo emplea vocalizaciones estereotipadas o palabras o frases raras, ya sea con presencia o no de otro lenguaje.'),
('4', 'A-4', 'Uso estereotipado o idiosincrásico de palabras o frases', 'Lenguaje y Comunicación', 3, 'Las frases son casi exclusivamente vocalizaciones raras o estereotipadas.'),

('4', 'A-5', 'Ofrece información', 'Lenguaje y Comunicación', 0, 'En varias ocasiones ofrece información espontáneamente sobre sus pensamientos, sentimientos o experiencias.'),
('4', 'A-5', 'Ofrece información', 'Lenguaje y Comunicación', 1, 'Ocasionalmente ofrece información de manera espontánea sobre sus pensamientos, sentimientos o experiencias.'),
('4', 'A-5', 'Ofrece información', 'Lenguaje y Comunicación', 2, 'Rara vez o nunca ofrece información de forma espontánea a no ser que sea acerca de sus intereses circunscritos o preocupaciones; o informa acerca de hechos o conocimientos generales, incluyendo las preocupaciones o intereses circunscritos.'),

('4', 'A-6', 'Pide información', 'Lenguaje y Comunicación', 0, 'Le pregunta al examinador sobre sus pensamientos, sentimientos o experiencias en varias ocasiones.'),
('4', 'A-6', 'Pide información', 'Lenguaje y Comunicación', 1, 'Ocasionalmente (por lo menos un ejemplo claro) le pregunta al examinador sobre sus pensamientos, sentimientos o experiencias.'),
('4', 'A-6', 'Pide información', 'Lenguaje y Comunicación', 2, 'Responde adecuadamente a los comentarios hechos por el examinador acerca de sus pensamientos, sentimientos o experiencias, pero espontáneamente no hace preguntas sobre ellos.'),
('4', 'A-6', 'Pide información', 'Lenguaje y Comunicación', 3, 'Rara vez o nunca le pregunta al examinador acerca de sus pensamientos, sentimientos o experiencias, ni expresa interés por ellos.'),

('4', 'A-7', 'Narración de sucesos', 'Lenguaje y Comunicación', 0, 'Da un informe de un hecho no-rutinario específico que no es parte de una preocupación o de un marcado interés y que pareciera ser real. Da un informe razonable sin necesitar preguntas específicas para ayudarlo.'),
('4', 'A-7', 'Narración de sucesos', 'Lenguaje y Comunicación', 1, 'Da un informe razonable de un hecho rutinario que no es parte de una preocupación o de un marcado interés y pareciera ser real. Da este informe sin preguntas específicas que lo guíen. Se incluyen aquí las respuestas a la tarea de demostración.'),
('4', 'A-7', 'Narración de sucesos', 'Lenguaje y Comunicación', 2, 'Da información acerca de un hecho rutinario o no-rutinario, pero depende de las preguntas específicas del examinador para poder continuar; o únicamente describe una situación que no pareciera poder ser real.'),
('4', 'A-7', 'Narración de sucesos', 'Lenguaje y Comunicación', 3, 'Respuestas inconsistentes o insuficientes, inclusive a las preguntas específicas.'),

('4', 'A-8', 'Conversación', 'Lenguaje y Comunicación', 0, 'La conversación fluye, construyéndose sobre el diálogo del examinador. Requiere secuencias de al menos cuatro elementos de intercambio recíproco.'),
('4', 'A-8', 'Conversación', 'Lenguaje y Comunicación', 1, 'Parte del habla del individuo incluye algo de elaboración espontánea de sus propias respuestas; o da pautas y entradas al examinador para que pueda seguir la conversación, pero la cantidad de habla es menor a la esperada o está limitada en cuanto a flexibilidad.'),
('4', 'A-8', 'Conversación', 'Lenguaje y Comunicación', 2, 'Poca conversación recíproca sostenida por el individuo; puede seguir su propio tren de pensamiento más que participar en un intercambio; puede hacer algún ofrecimiento espontáneo de información pero con escaso sentido de la reciprocidad.'),
('4', 'A-8', 'Conversación', 'Lenguaje y Comunicación', 3, 'Poca habla comunicativa espontánea. Asigne este código a aquellos individuos que emiten algunas respuestas limitadas, pero muy escasas.'),

('4', 'A-9', 'Gestos descriptivos, convencionales, instrumentales o informativos', 'Lenguaje y Comunicación', 0, 'Uso espontáneo de varios gestos descriptivos. Los gestos pueden ser típicos o idiosincrásicos, pero deben ser comunicativos. Puede usar además gestos convencionales o instrumentales.'),
('4', 'A-9', 'Gestos descriptivos, convencionales, instrumentales o informativos', 'Lenguaje y Comunicación', 1, 'Algún uso espontáneo de gestos descriptivos, pero exagerado o limitado en el rango o variedad de contextos; o uso frecuente de gestos convencionales o instrumentales, pero no descriptivos.'),
('4', 'A-9', 'Gestos descriptivos, convencionales, instrumentales o informativos', 'Lenguaje y Comunicación', 2, 'Algún uso espontáneo de gestos informativos, convencionales o instrumentales, pero no descriptivos.'),
('4', 'A-9', 'Gestos descriptivos, convencionales, instrumentales o informativos', 'Lenguaje y Comunicación', 3, 'Poco o ningún uso de gestos convencionales, instrumentales, informativos o descriptivos.'),
('4', 'A-9', 'Gestos descriptivos, convencionales, instrumentales o informativos', 'Lenguaje y Comunicación', 8, 'N/A (limitado por alguna discapacidad física).'),

('4', 'A-10', 'Gestos enfáticos o emocionales', 'Lenguaje y Comunicación', 0, 'Variedad de gestos enfáticos o emocionales bien integrados en el habla.'),
('4', 'A-10', 'Gestos enfáticos o emocionales', 'Lenguaje y Comunicación', 1, 'Algunos gestos enfáticos o emocionales pero exagerados; o gestos limitados en frecuencia, en estilo, en su integración en el habla o en su oportunidad o idoneidad.'),
('4', 'A-10', 'Gestos enfáticos o emocionales', 'Lenguaje y Comunicación', 2, 'Gestos enfáticos o emocionales extraños, excesivos o claramente mal integrados en el habla.'),
('4', 'A-10', 'Gestos enfáticos o emocionales', 'Lenguaje y Comunicación', 3, 'Escasos o nulos gestos enfáticos o emocionales.'),
('4', 'A-10', 'Gestos enfáticos o emocionales', 'Lenguaje y Comunicación', 8, 'La cantidad de lenguaje espontáneo es insuficiente como para poder juzgar los gestos que lo acompañan.'),

-- B. Interacción Social Recíproca
('4', 'B-1', 'Contacto visual inusual', 'Interacción Social Recíproca', 0, 'Mirada apropiada, con cambios sutiles entremezclados con otro tipo de comunicación.'),
('4', 'B-1', 'Contacto visual inusual', 'Interacción Social Recíproca', 2, 'Establece un contacto visual pobremente modulado socialmente para iniciar, terminar o regular una interacción social.'),

('4', 'B-2', 'Expresiones faciales dirigidas a otros', 'Interacción Social Recíproca', 0, 'Dirige una variedad de expresiones faciales apropiadas al examinador o a otra persona con la intención de comunicar emociones.'),
('4', 'B-2', 'Expresiones faciales dirigidas a otros', 'Interacción Social Recíproca', 1, 'Dirige algunas expresiones faciales al examinador o a otra persona (p. ej., dirige únicamente expresiones que indiquen emociones extremas u ocasionalmente dirige una variedad más amplia de expresiones). Se le puede asignar este código a un individuo que tenga una variedad limitada de expresiones pero que dirige la mayoría de sus expresiones a otra persona.'),
('4', 'B-2', 'Expresiones faciales dirigidas a otros', 'Interacción Social Recíproca', 2, 'Rara vez o nunca dirige expresiones faciales apropiadas a otros.'),

('4', 'B-3', 'Producción de lenguaje y comunicación no verbal vinculada', 'Interacción Social Recíproca', 0, 'La vocalización en general se acompaña de cambios sutiles y socialmente adecuados en los gestos, las miradas y las expresiones faciales.'),
('4', 'B-3', 'Producción de lenguaje y comunicación no verbal vinculada', 'Interacción Social Recíproca', 1, 'La vocalización se acompaña de una variedad o frecuencia de gestos, miradas y expresiones faciales anormal, limitada o inferior a la usual; o usa casi exclusivamente una sola modalidad.'),
('4', 'B-3', 'Producción de lenguaje y comunicación no verbal vinculada', 'Interacción Social Recíproca', 2, 'Escasa o nula comunicación no verbal en conjunción con las vocalizaciones.'),
('4', 'B-3', 'Producción de lenguaje y comunicación no verbal vinculada', 'Interacción Social Recíproca', 7, 'Cierta evitación de la mirada, quizás debida a timidez, pero muestra cierta modulación y coordinación del lenguaje y las conductas no verbales.'),
('4', 'B-3', 'Producción de lenguaje y comunicación no verbal vinculada', 'Interacción Social Recíproca', 8, 'N/A; no hubo vocalizaciones; o el empleo de gestos, expresiones faciales o miradas socialmente dirigidas fue mínimo o nulo.'),

('4', 'B-4', 'Placer compartido durante la interacción', 'Interacción Social Recíproca', 0, 'Muestra claros y apropiados signos de disfrute durante un intercambio interactivo o conversacional en más de una actividad o tema de conversación.'),
('4', 'B-4', 'Placer compartido durante la interacción', 'Interacción Social Recíproca', 1, 'Expresa algo de goce apropiado en las acciones del examinador; o muestra claros signos de placer durante una sola interacción.'),
('4', 'B-4', 'Placer compartido durante la interacción', 'Interacción Social Recíproca', 2, 'Expresa escaso o nulo placer en la interacción con el examinador. Puede expresar placer en sus propias actividades o en partes de la conversación, pero no en los comportamientos del examinador o en su interacción con él.'),
('4', 'B-4', 'Placer compartido durante la interacción', 'Interacción Social Recíproca', 8, 'No se puede valorar este ítem ya sea porque la interacción existente ha sido escasa o nula o por otras razones.'),

('4', 'B-5', 'Comunicación de sus propias emociones', 'Interacción Social Recíproca', 0, 'Comunica de manera efectiva una variedad de emociones que está sintiendo o ha sentido.'),
('4', 'B-5', 'Comunicación de sus propias emociones', 'Interacción Social Recíproca', 1, 'Cierta descripción de haber sentido varias emociones, pero limitada en variedad o en capacidad para poder comunicarlas adecuadamente (puede transmitir una emoción de un modo efectivo).'),
('4', 'B-5', 'Comunicación de sus propias emociones', 'Interacción Social Recíproca', 2, 'Comunica una sola emoción con una mínima descripción de otras.'),
('4', 'B-5', 'Comunicación de sus propias emociones', 'Interacción Social Recíproca', 3, 'Escasa o nula comunicación de sus propias emociones.'),

('4', 'B-6', 'Empatía / comentarios sobre las emociones de otros', 'Interacción Social Recíproca', 0, 'Transmite que claramente comprende y comparte la emoción de otros en emociones variadas y diferentes.'),
('4', 'B-6', 'Empatía / comentarios sobre las emociones de otros', 'Interacción Social Recíproca', 1, 'Transmite que en cierto grado comprende y comparte la emoción de otros en más de una emoción; o transmite que claramente comprende y comparte una emoción experimentada por otro individuo.'),
('4', 'B-6', 'Empatía / comentarios sobre las emociones de otros', 'Interacción Social Recíproca', 2, 'Transmite que en cierto grado comprende o comparte al menos una experiencia emocional de otro individuo.'),
('4', 'B-6', 'Empatía / comentarios sobre las emociones de otros', 'Interacción Social Recíproca', 3, 'Escasa o nula manifestación de que comprende o comparte estados emocionales.'),

('4', 'B-7', 'Insight (comprensión de relaciones sociales)', 'Interacción Social Recíproca', 0, 'Muestra varios ejemplos de comprensión de la naturaleza de relaciones sociales típicas, incluyendo la comprensión de su propio rol en al menos una de ellas.'),
('4', 'B-7', 'Insight (comprensión de relaciones sociales)', 'Interacción Social Recíproca', 1, 'Muestra ejemplos de comprensión de varias relaciones sociales típicas, pero no de su propio rol dentro de ellas; o muestra comprensión de sólo una relación y de su rol en ella.'),
('4', 'B-7', 'Insight (comprensión de relaciones sociales)', 'Interacción Social Recíproca', 2, 'Muestra cierta comprensión de una sola relación social, pero no necesariamente de su rol en esa relación.'),
('4', 'B-7', 'Insight (comprensión de relaciones sociales)', 'Interacción Social Recíproca', 3, 'Muestra una comprensión escasa o nula de las relaciones sociales típicas, con o sin conocimiento sobre su rol en ellas.'),

('4', 'B-8', 'Responsabilidad', 'Interacción Social Recíproca', 0, 'Se ve como responsable de sus propias acciones en varios contextos, incluso cuando se trata de problemas menores de la vida diaria.'),
('4', 'B-8', 'Responsabilidad', 'Interacción Social Recíproca', 1, 'Brinda por lo menos una indicación clara de percibirse a sí mismo como responsable de sus propias acciones. No debe mostrar más de un ejemplo claro de falta de responsabilidad. No es consistente a lo largo de varios contextos.'),
('4', 'B-8', 'Responsabilidad', 'Interacción Social Recíproca', 2, 'Muestra escasos indicios de sentido de la responsabilidad de sus propias acciones o muestra varios ejemplos claros de una falta de responsabilidad que sí sería esperable a su edad cronológica.'),

('4', 'B-9', 'Cualidad de los acercamientos sociales', 'Interacción Social Recíproca', 0, 'Uso efectivo de formas verbales y no-verbales para hacer claros acercamientos sociales hacia el examinador. Los acercamientos deben ser apropiados al contexto inmediato.'),
('4', 'B-9', 'Cualidad de los acercamientos sociales', 'Interacción Social Recíproca', 1, 'Cualidad levemente inusual de algunos acercamientos sociales. Pueden restringirse a demandas personales o estar relacionados con intereses propios del individuo, pero con alguna intención de incluir al examinador en ese interés.'),
('4', 'B-9', 'Cualidad de los acercamientos sociales', 'Interacción Social Recíproca', 2, 'Acercamientos inapropiados; muchos acercamientos carecen de integración en el contexto o carecen de cualidad social. Incluye plantear preocupaciones pero con escasa intención de implicar al examinador.'),
('4', 'B-9', 'Cualidad de los acercamientos sociales', 'Interacción Social Recíproca', 3, 'Insignificante cantidad de acercamientos sociales de cualquier tipo.'),

('4', 'B-10', 'Cualidad de la respuesta social', 'Interacción Social Recíproca', 0, 'Gama de respuestas apropiadas que varían de acuerdo a las situaciones y presiones sociales inmediatas.'),
('4', 'B-10', 'Cualidad de la respuesta social', 'Interacción Social Recíproca', 1, 'Muestra respuesta a la mayoría de las situaciones sociales, pero algo limitada, socialmente rara, inapropiada, inconsistente o consistentemente negativa.'),
('4', 'B-10', 'Cualidad de la respuesta social', 'Interacción Social Recíproca', 2, 'Respuestas raras o estereotipadas o respuestas con poca variación o inapropiadas al contexto.'),
('4', 'B-10', 'Cualidad de la respuesta social', 'Interacción Social Recíproca', 3, 'Mínima o inexistente respuesta a los intentos por parte del examinador de involucrar al individuo.'),

('4', 'B-11', 'Cantidad de comunicación social recíproca', 'Interacción Social Recíproca', 0, 'Hace un amplio uso de comportamientos verbales o no verbales para obtener intercambio social.'),
('4', 'B-11', 'Cantidad de comunicación social recíproca', 'Interacción Social Recíproca', 1, 'Muestra algo de comunicación social recíproca, pero reducida en frecuencia o cantidad o en número de contextos.'),
('4', 'B-11', 'Cantidad de comunicación social recíproca', 'Interacción Social Recíproca', 2, 'La mayor parte de la comunicación está relacionada con un objeto o en respuesta a una pregunta; o es ecolálica; o tiene que ver con ciertas preocupaciones. Hay poca charla social o de ida y vuelta.'),
('4', 'B-11', 'Cantidad de comunicación social recíproca', 'Interacción Social Recíproca', 3, 'Escasa o nula comunicación social recíproca.'),

('4', 'B-12', 'Cualidad general del rapport', 'Interacción Social Recíproca', 0, 'Interacción cómoda con el examinador, apropiada al contexto.'),
('4', 'B-12', 'Cualidad general del rapport', 'Interacción Social Recíproca', 1, 'Interacción cómoda por momentos, pero no sostenida (a veces se percibe como rara o artificial o el comportamiento del individuo pareciera mecánico o ligeramente inapropiado).'),
('4', 'B-12', 'Cualidad general del rapport', 'Interacción Social Recíproca', 2, 'Interacción unilateral o inusual convirtiéndose en una entrevista que es levemente incómoda de forma consistente o una entrevista que hubiera sido difícil si el examinador no hubiera estado constantemente re-estructurando la situación.'),
('4', 'B-12', 'Cualidad general del rapport', 'Interacción Social Recíproca', 3, 'El individuo muestra poca consideración por el examinador; o la entrevista resulta considerablemente incómoda durante una parte significativa del tiempo.'),

-- C. Imaginación
('4', 'C-1', 'Imaginación y creatividad', 'Imaginación', 0, 'Variedad de actividades o comentarios en la conversación que fueron creativos, originales y espontáneos.'),
('4', 'C-1', 'Imaginación y creatividad', 'Imaginación', 1, 'Algunas acciones imaginativas o creativas, pero limitadas en su variedad o en que ocurren solo en respuesta a una situación estructurada.'),
('4', 'C-1', 'Imaginación y creatividad', 'Imaginación', 2, 'Escasas acciones imaginativas o creativas; o solo presenta acciones que son de cualidad repetitiva o estereotipada.'),
('4', 'C-1', 'Imaginación y creatividad', 'Imaginación', 3, 'No hay acciones creativas o inventivas (ni siquiera repetitivas o estereotipadas).'),

-- D. Comportamientos Estereotipados e Intereses Restringidos
('4', 'D-1', 'Interés sensorial inusual en los materiales de juego o las personas', 'Comportamientos Estereotipados e Intereses Restringidos', 0, 'No realiza ninguna acción sensorial inusual (olisquear, tocar repetidamente, palpar texturas, lamer o morder, meterse algo en la boca, interés por repetir ciertos sonidos, examen visual prolongado o inusual).'),
('4', 'D-1', 'Interés sensorial inusual en los materiales de juego o las personas', 'Comportamientos Estereotipados e Intereses Restringidos', 1, 'Intereses sensoriales inusuales ocasionales; o no son tan claros como lo especificado para código 2.'),
('4', 'D-1', 'Interés sensorial inusual en los materiales de juego o las personas', 'Comportamientos Estereotipados e Intereses Restringidos', 2, 'Claro interés por elementos no funcionales de los materiales de juego; o examinación sensorial de sí mismo o de otros.'),

('4', 'D-2', 'Manierismos de manos y dedos y otros manierismos complejos', 'Comportamientos Estereotipados e Intereses Restringidos', 0, 'Ninguno.'),
('4', 'D-2', 'Manierismos de manos y dedos y otros manierismos complejos', 'Comportamientos Estereotipados e Intereses Restringidos', 1, 'Manierismos de manos o dedos o manierismos complejos breves u ocasionales; o manierismos que no son tan claros como se especifica en el código 2.'),
('4', 'D-2', 'Manierismos de manos y dedos y otros manierismos complejos', 'Comportamientos Estereotipados e Intereses Restringidos', 2, 'Hay evidentes movimientos, sacudidas o retorcimientos de dedos o manos u otros manierismos o estereotipias.'),

('4', 'D-3', 'Conductas autolesivas', 'Comportamientos Estereotipados e Intereses Restringidos', 0, 'No intenta autolesionarse.'),
('4', 'D-3', 'Conductas autolesivas', 'Comportamientos Estereotipados e Intereses Restringidos', 1, 'Rara vez se autolesiona o no es claro (p. ej., por lo menos una vez se muerde la mano o el brazo, o se tira del pelo, se abofetea su propia cara o se golpea la cabeza).'),
('4', 'D-3', 'Conductas autolesivas', 'Comportamientos Estereotipados e Intereses Restringidos', 2, 'Autolesión claramente presente (más de una vez se golpea la cabeza, se abofetea, se tira del pelo o se muerde).'),

('4', 'D-4', 'Excesivo interés o referencias a temas u objetos inusuales o altamente específicos o comportamientos repetitivos', 'Comportamientos Estereotipados e Intereses Restringidos', 0, 'No hubo un excesivo interés o referencias a objetos o temas inusuales o altamente específicos o restringidos.'),
('4', 'D-4', 'Excesivo interés o referencias a temas u objetos inusuales o altamente específicos o comportamientos repetitivos', 'Comportamientos Estereotipados e Intereses Restringidos', 1, 'Referencias ocasionales a temas o patrones de interés inusuales o altamente específicos, que suceden en un grado inusual.'),
('4', 'D-4', 'Excesivo interés o referencias a temas u objetos inusuales o altamente específicos o comportamientos repetitivos', 'Comportamientos Estereotipados e Intereses Restringidos', 2, 'Patrones de intereses estereotipados o inusuales claramente presentes, que pueden o no interferir con la comunicación social.'),
